//! Parity test against the original Go implementation.
//!
//! The golden file `tests/golden/color_ops.txt` is generated by running the
//! reference program:
//!
//! ```text
//! go run -C reference/go/charm-color ./cmd/parity
//! ```
//!
//! and comparing it byte-for-byte with the output produced here.

use std::fmt::Write as _;

use charm_color::{blend, complementary, contrast, darken, from_lipgloss, lighten, palette};
use charm_core::Rgb;

/// Renders a color the same way the Go reference program does.
fn show(color: Rgb) -> String {
    format!("{}/{}", color.to_hex(), color.a)
}

/// Renders a palette the same way the Go reference program does.
fn show_palette(colors: &[Rgb]) -> String {
    if colors.is_empty() {
        return "(empty)".to_owned();
    }
    colors
        .iter()
        .map(|color| show(*color))
        .collect::<Vec<_>>()
        .join(", ")
}

/// Writes a line into the output buffer.
fn line(out: &mut String, text: &str) {
    out.push_str(text);
    out.push('\n');
}

/// The `darken` vectors.
fn darken_section() -> String {
    let mut out = String::new();
    for (color, amount) in [
        (Rgb::new(200, 100, 50, 255), 0.0),
        (Rgb::new(200, 100, 50, 255), 0.25),
        (Rgb::new(200, 100, 50, 255), 0.5),
        (Rgb::new(200, 100, 50, 255), 0.75),
        (Rgb::new(200, 100, 50, 255), 1.0),
        (Rgb::new(200, 100, 50, 255), 1.5),
        (Rgb::new(200, 100, 50, 255), -0.5),
        (Rgb::new(255, 255, 255, 255), 0.5),
        (Rgb::new(0, 0, 0, 255), 0.3),
        (Rgb::new(12, 34, 56, 128), 0.4),
    ] {
        writeln!(
            out,
            "darken {} {} {} {} {amount:.4} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            show(darken(color, amount))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `lighten` vectors.
fn lighten_section() -> String {
    let mut out = String::new();
    for (color, amount) in [
        (Rgb::new(100, 50, 25, 255), 0.0),
        (Rgb::new(100, 50, 25, 255), 0.25),
        (Rgb::new(100, 50, 25, 255), 0.5),
        (Rgb::new(100, 50, 25, 255), 0.75),
        (Rgb::new(100, 50, 25, 255), 1.0),
        (Rgb::new(100, 50, 25, 255), 1.5),
        (Rgb::new(100, 50, 25, 255), -0.5),
        (Rgb::new(0, 0, 0, 255), 0.5),
        (Rgb::new(255, 255, 255, 255), 0.25),
        (Rgb::new(12, 34, 56, 128), 0.4),
    ] {
        writeln!(
            out,
            "lighten {} {} {} {} {amount:.4} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            show(lighten(color, amount))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `blend` vectors.
fn blend_section() -> String {
    let mut out = String::new();
    for (c1, c2, t) in [
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 0.0),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 0.25),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 0.5),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 0.75),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 1.0),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), 1.5),
        (Rgb::new(0, 0, 0, 255), Rgb::new(255, 255, 255, 255), -0.5),
        (Rgb::new(255, 0, 0, 255), Rgb::new(0, 0, 255, 255), 0.5),
        (Rgb::new(10, 20, 30, 255), Rgb::new(40, 50, 60, 255), 0.33),
        (Rgb::new(10, 20, 30, 128), Rgb::new(40, 50, 60, 255), 0.5),
    ] {
        writeln!(
            out,
            "blend {} {} {} {} {} {} {} {} {t:.4} -> {}",
            c1.r,
            c1.g,
            c1.b,
            c1.a,
            c2.r,
            c2.g,
            c2.b,
            c2.a,
            show(blend(c1, c2, t))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `contrast` vectors.
fn contrast_section() -> String {
    let mut out = String::new();
    for color in [
        Rgb::new(0, 0, 0, 255),
        Rgb::new(255, 255, 255, 255),
        Rgb::new(200, 100, 50, 255),
        Rgb::new(128, 128, 128, 255),
        Rgb::new(255, 0, 0, 255),
        Rgb::new(0, 255, 0, 255),
        Rgb::new(0, 0, 255, 255),
        Rgb::new(250, 189, 47, 255),
    ] {
        writeln!(
            out,
            "contrast {} {} {} {} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            show(contrast(color))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `complementary` vectors.
fn complementary_section() -> String {
    let mut out = String::new();
    for color in [
        Rgb::new(255, 0, 0, 255),
        Rgb::new(200, 100, 50, 255),
        Rgb::new(0, 0, 0, 255),
        Rgb::new(255, 255, 255, 255),
        Rgb::new(18, 52, 86, 255),
    ] {
        writeln!(
            out,
            "complementary {} {} {} {} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            show(complementary(color))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `palette` vectors.
fn palette_section() -> String {
    let mut out = String::new();
    for (color, count) in [
        (Rgb::new(255, 0, 0, 255), 4),
        (Rgb::new(52, 152, 219, 255), 6),
        (Rgb::new(128, 128, 128, 255), 3),
        (Rgb::new(255, 0, 255, 255), 4),
        (Rgb::new(0, 255, 0, 255), 3),
        (Rgb::new(0, 0, 255, 255), 3),
        (Rgb::new(250, 189, 47, 255), 5),
        (Rgb::new(255, 0, 0, 255), 1),
        (Rgb::new(255, 0, 0, 255), 0),
    ] {
        writeln!(
            out,
            "palette {} {} {} {} {count} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            show_palette(&palette(color, count))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `ToHex` vectors.
fn tohex_section() -> String {
    let mut out = String::new();
    for color in [
        Rgb::new(255, 128, 0, 255),
        Rgb::new(0, 0, 0, 255),
        Rgb::new(255, 255, 255, 255),
        Rgb::new(200, 100, 50, 255),
    ] {
        writeln!(
            out,
            "tohex {} {} {} {} -> {}",
            color.r,
            color.g,
            color.b,
            color.a,
            color.to_hex()
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `FromHex` vectors, including the invalid inputs.
fn fromhex_section() -> String {
    let mut out = String::new();
    for value in [
        "#ff8000", "00ff00", "invalid", "#ff00", "", "#zzzzzz", "ABCDEF",
    ] {
        writeln!(
            out,
            "fromhex {value:?} -> {}",
            show(Rgb::from_hex_or_black(value))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// The `FromLipgloss` vectors, including the invalid inputs.
fn fromlipgloss_section() -> String {
    let mut out = String::new();
    for value in [
        "#ff8000", "#fff", "63", "5", "255", "1", "invalid", "", "#zzz",
    ] {
        writeln!(
            out,
            "fromlipgloss {value:?} -> {}",
            show(from_lipgloss(value))
        )
        .expect("writing to a String never fails");
    }
    out
}

/// Builds the whole reference output, mirroring `cmd/parity/main.go`.
fn reference_output() -> String {
    let mut out = String::new();
    line(&mut out, "# charm-color parity vectors");
    line(&mut out, "# <op> <args> -> <#rrggbb/alpha>");
    line(&mut out, "[darken]");
    out.push_str(&darken_section());
    line(&mut out, "[lighten]");
    out.push_str(&lighten_section());
    line(&mut out, "[blend]");
    out.push_str(&blend_section());
    line(&mut out, "[contrast]");
    out.push_str(&contrast_section());
    line(&mut out, "[complementary]");
    out.push_str(&complementary_section());
    line(&mut out, "[palette]");
    out.push_str(&palette_section());
    line(&mut out, "[tohex]");
    out.push_str(&tohex_section());
    line(&mut out, "[fromhex]");
    out.push_str(&fromhex_section());
    line(&mut out, "[fromlipgloss]");
    out.push_str(&fromlipgloss_section());
    out
}

/// The whole color API must match the Go original byte-for-byte.
#[test]
fn color_ops_match_go_reference() {
    charm_parity::assert_golden("color_ops", &reference_output());
}
